function InputGroup({text,id}) {
  return (
    <div className=' flex flex-col  w-3/4 md:w-1/2 text-white text-lg'>
        <label htmlFor={id}>
            Lable
        </label>
        <input type="text" name="" id="" className=' rounded-lg relative w-full bg-gray-700' />
    </div>
  )
}

export default InputGroup
